g=[[0,0,0,2,2,0,2],[0,2,2,9,2,2,0],[0,5,0,2,4,6,0],[2,0,0,0,0,9,2],[0,0,0,2,2,0,0],[8,0,2,9,0,6,3],[0,2,0,2,0,2,4]]
outs=['000/111/000']
for i in range(5):
 for j in range(5):
  w=[r[j:j+3] for r in g[i:i+3]]
  for v in set(sum(w,[])):
   for sense in ('eq','neq'):
    b=tuple(tuple(int(x==v if sense=='eq' else x!=v) for x in row) for row in w)
